import{_ as i,l as s,o as e,c as l,v as t,p as o,x as r,d as p,i as n,S as _}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"组合逻辑时延","description":"","frontmatter":{"title":"组合逻辑时延","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/gate-delay.md","filePath":"cs/gate-delay.md","lastUpdated":1789023840000}'),c={name:"cs/gate-delay.md"};function h(E,a,A,m,u,D){const d=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="组合逻辑时延" tabindex="-1">组合逻辑时延 <a class="header-anchor" href="#组合逻辑时延" aria-label="Permalink to &quot;组合逻辑时延&quot;">​</a></h1><div class="epigraph"><p>功能对了还不够：输出必须在最坏输入变化后的某个时刻才稳定，那个时刻就是传播延迟。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p>上一课<a href="/cs/transmission-tristate">传输门与三态</a>钉死了任意组合功能都能落成门网。本课不重证 NAND 完备，也不从电磁场另起。缺口是：卡诺图与布尔式都不含时间。CMOS 对电容充放电需要时间；后课时钟周期不能短于这段时间。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>网表在直流上实现 \\(f\\)。输入同时变，输出要经过若干级才到新值，途中可以有<a href="/cs/dont-care-hazard">险象课</a>的毛刺。缺口因此不是新门，而是两个数：\\(t_{pd}\\) 传播延迟（最坏稳定时间）、\\(t_{cd}\\) 污染延迟（最早可能变）。时序约束用前者定周期下界，用后者防保持时间失败——保持是<a href="/cs/setup-hold">建立保持</a>的缺口，本课先把组合块当成有延迟的盒子。</p><p>关键路径是拓扑上延迟之和最大的那条。本课用单位门延迟作加法模型，不把 RC 树 Elmore 公式写完。</p><h3 id="不是仿真里「看起来稳了」的一次波形" tabindex="-1">\\(t_{pd}\\) 不是仿真里「看起来稳了」的一次波形 <a class="header-anchor" href="#不是仿真里「看起来稳了」的一次波形" aria-label="Permalink to &quot;$t_{pd}$ 不是仿真里「看起来稳了」的一次波形&quot;">​</a></h3><p>必须对输入对、温度、工艺角取最坏。功能仿真通过不等于时序通过。把扇出当成免费，关键路径会少算几级反相器缓冲。</p><p><span class="marginnote">Harris 把组合逻辑画成带 \\(t_{pd}\\)/\\(t_{cd}\\) 的云。后课单周期 CPU 的周期就是最长指令的组合路径。本课不引入触发器。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每级门赋延迟（可按扇入扇出加权）。\\(t_{pd}(\\mathrm{path})=\\sum t_{pd,i}\\)，电路 \\(t_{pd}\\) 取全体输入-输出路径最大。污染延迟取最小。多级化简可能减逻辑深度，但扇出变大，延迟不一定降——与卡诺图「项更少」不是同一目标。</p>',11)),(e(),o(_,null,{default:r(()=>[n(d,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20NET%5B%22%E5%8A%9F%E8%83%BD%E6%AD%A3%E7%A1%AE%E7%9A%84%E7%BD%91%E8%A1%A8%22%5D%20--%3E%20DEL%5B%22%E6%AF%8F%E7%BA%A7%E5%85%85%E6%94%BE%E7%94%B5%22%5D%0A%20%20DEL%20--%3E%20TPD%5B%22t_pd%20%E6%9C%80%E5%9D%8F%E7%A8%B3%E5%AE%9A%22%5D%0A%20%20DEL%20--%3E%20TCD%5B%22t_cd%20%E6%9C%80%E6%97%A9%E5%8F%98%22%5D%0A%20%20TPD%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9AMUX%20%E7%AD%89%E5%9D%97%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>后课加法器的行波进位 \\(t_{pd}\\) 随位宽线性涨，才有超前进位。MUX、ALU 都先当组合云，用本课的尺子比深度。时钟仍未进场：组合电路没有「周期」，只有从输入变到输出稳的时间。</p><p>险象的毛刺落在 \\(t_{cd}\\) 与 \\(t_{pd}\\) 之间。若下游是纯组合，毛刺继续走；若下游是边沿采样，要看是否落在窗口外。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲时钟树、不讲互连铜线上的飞行时间作为主模型（承认线电容折进门负载即可）。不把异步组合反馈（环振）当合法数字设计——那是有意的模拟/测试结构。</p><p>后课默认：每个组合块带 \\(t_{pd}\\)、\\(t_{cd}\\)；关键路径决定后课能跑多快。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>组合正确性之外必须计量 \\(t_{pd}\\) 与 \\(t_{cd}\\)。</li><li>关键路径是最坏延迟和；项数少不等于深度小。</li><li>时钟与触发器仍未出现；本课只给组合盒子贴时间。</li><li>出处：Harris and Harris。</li></ul>',8))])}const B=i(c,[["render",h]]);export{T as __pageData,B as default};
